import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"9.3 配电箱与配电柜","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-3-pei-dian-xiang-yu-pei-dian-gui.md","filePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-3-pei-dian-xiang-yu-pei-dian-gui.md","lastUpdated":1793095197000}'),n={name:"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-3-pei-dian-xiang-yu-pei-dian-gui.md"};function r(e,t,s,d,g,c){return i(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="_9-3-配电箱与配电柜" tabindex="-1">9.3 配电箱与配电柜 <a class="header-anchor" href="#_9-3-配电箱与配电柜" aria-label="Permalink to &quot;9.3 配电箱与配电柜&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>配电箱和配电柜是&quot;电的分发站&quot;:总开关把电接进来,分路开关把电送出去。这一节认识它们的组成、基本配置和安全要求。</p><h2 id="一、配电箱的作用与组成" tabindex="-1">一、配电箱的作用与组成 <a class="header-anchor" href="#一、配电箱的作用与组成" aria-label="Permalink to &quot;一、配电箱的作用与组成&quot;">​</a></h2><p><strong>配电箱(柜)</strong>:集中安装开关、保护电器、测量仪表的成套低压配电装置,把总电源分配给各分路负荷。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进线(总开关) ──► 母线 ──► 分路开关1 ──► 回路1</span></span>
<span class="line"><span>                        ├─ 分路开关2 ──► 回路2</span></span>
<span class="line"><span>                        └─ 分路开关3 ──► 回路3</span></span></code></pre></div><p>主要组成:</p><table tabindex="0"><thead><tr><th>元件</th><th>作用</th></tr></thead><tbody><tr><td><strong>总开关</strong>(隔离开关/总断路器)</td><td>接通、断开总电源,方便检修</td></tr><tr><td><strong>分路断路器/熔断器</strong></td><td>每条支路的保护(短路、过载)</td></tr><tr><td><strong>母线(汇流排)</strong></td><td>把电能汇集后分配给各分路</td></tr><tr><td><strong>漏电保护器</strong></td><td>漏电、人身触电保护(插座回路必配)</td></tr><tr><td><strong>电流表/电压表</strong></td><td>监视电流、电压</td></tr></tbody></table><h2 id="二、配电箱-柜-的基本配置要求" tabindex="-1">二、配电箱(柜)的基本配置要求 <a class="header-anchor" href="#二、配电箱-柜-的基本配置要求" aria-label="Permalink to &quot;二、配电箱(柜)的基本配置要求&quot;">​</a></h2><ul><li>每个回路都要有<strong>过载和短路保护</strong>(断路器或熔断器);</li><li>插座回路、移动设备回路要装<strong>漏电保护器</strong>;</li><li>箱(柜)的<strong>金属外壳要可靠接地</strong>(接 PE 线);</li><li>导线颜色区分:<strong>相线</strong>用黄、绿、红,<strong>中性线(N)用淡蓝色,保护零线(PE)用黄绿双色</strong>;</li><li>箱内导线要<strong>分色、扎紧、编号</strong>,进出线要有余量。</li></ul><blockquote><p>⚠️ 判断题常考:<strong>中性线(N)淡蓝色、保护零线(PE)黄绿双色</strong>——颜色不能混。</p></blockquote><h2 id="三、配电箱-柜-安装与使用要求" tabindex="-1">三、配电箱(柜)安装与使用要求 <a class="header-anchor" href="#三、配电箱-柜-安装与使用要求" aria-label="Permalink to &quot;三、配电箱(柜)安装与使用要求&quot;">​</a></h2><ul><li>安装牢固、通风干燥,箱门要能正常开关;</li><li><strong>箱内不得堆放杂物</strong>,元件间留足散热空间;</li><li>箱前要留操作空间,标明回路名称、编号;</li><li>检修时<strong>先断总开关,再验电</strong>,确认无电再操作;</li><li>定期检查接线是否松动、发热,漏电保护器要<strong>定期试验(按&quot;试验按钮&quot;)</strong>。</li></ul><blockquote><p>💡 漏电保护器每月应<strong>按一次试验按钮</strong>检查能否正常跳闸。</p></blockquote><h2 id="四、配电箱与配电柜的区别-简说" tabindex="-1">四、配电箱与配电柜的区别(简说) <a class="header-anchor" href="#四、配电箱与配电柜的区别-简说" aria-label="Permalink to &quot;四、配电箱与配电柜的区别(简说)&quot;">​</a></h2><ul><li><strong>配电箱</strong>:小型的、容量较小的配电装置,常装在墙上、室内;</li><li><strong>配电柜(屏、盘)</strong>:容量较大、元件较多,常立式安装(如低压配电柜),用于变电所或厂房。</li></ul><blockquote><p>💡 本质相同(都是配电装置),只是大小、安装形式不同。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 每个回路都应有<strong>过载和短路保护</strong>;插座回路装<strong>漏电保护</strong>。</li><li>✅ 配电箱金属外壳<strong>接地</strong>;箱内导线<strong>分色</strong>。</li><li>✅ N 线淡蓝色,PE 线黄绿双色,相线黄/绿/红。</li><li>⚠️ 易混点:总开关负责总切断,分路开关负责支路保护,漏电保护负责人身漏电安全——职责不同。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>配电箱是&quot;电的分发站&quot;:总开关 + 母线 + 分路开关 + 保护。</li><li>每个回路要保护,插座回路要漏电保护,外壳要接地。</li><li>导线分色规范:相线黄绿红、N 淡蓝、PE 黄绿双色。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)配电箱内每个回路都应有短路和过载保护。( )</li><li>(单选)配电箱内保护零线(PE 线)的标准颜色是()。 A. 黑色　B. 淡蓝色　C. 黄绿双色　D. 白色</li><li>(判断)配电箱的金属外壳应可靠接地。( )</li><li>(单选)插座回路必须安装的保护装置是()。 A. 隔离开关　B. 漏电保护器　C. 电压表　D. 电度表</li><li>(判断)漏电保护器应定期按试验按钮检查能否正常跳闸。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。每个回路都要有过载和短路保护。</li><li><strong>C</strong>。PE 线(保护零线)为黄绿双色。</li><li><strong>√</strong>。金属外壳必须可靠接地。</li><li><strong>B</strong>。插座回路必须装漏电保护器。</li><li><strong>√</strong>。定期试验是漏电保护器维护要求。</li></ol></details>`,24)])])}const p=a(n,[["render",r]]);export{u as __pageData,p as default};
